grammar.syntax:
let s1 = String::from("hello");
let s2 = s1; // move
let len = calculate_length(&s2);

grammar.example:
fn calculate_len(s: &str) -> usize {
    s.len()
}

fn main() {
    let s = String::from("Rust");
    println!("len: {}", calculate_len(&s));
}

grammar.syntax:
match val {
    Some(x) => println!("{}", x),
    None => (),
}

grammar.example:
fn main() {
    let opt: Option<i32> = Some(42);
    match opt {
        Some(n) => println!("value: {}", n),
        None => println!("empty"),
    }
}

grammar.syntax:
fn parse(s: &str) -> Result<i32, ParseIntError> {
    let n = s.parse::<i32>()?;
    Ok(n)
}

grammar.example:
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let num: i32 = "123".parse()?;
    println!("num: {}", num);
    Ok(())
}

struct Point { x: f64, y: f64 }

impl Point {
    fn new(x: f64, y: f64) -> Self {
        Self { x, y }
    }
}

fn main() {
    let p = Point::new(1.0, 2.0);
    println!("({}, {})", p.x, p.y);
}

fn main() {
    let nums = vec![1, 2, 3, 4, 5];
    let sum: i32 = nums.iter().filter(|&&x| x % 2 == 1).sum();
    println!("sum of odds: {}", sum);
}

use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        tx.send("hello from thread").unwrap();
    });
    println!("{}", rx.recv().unwrap());
}
